void dijkstra(int src, int n, vector<vector<pair<int,ll>>>& adj, vector<ll>& dist, vector<double>& cnt) {
    dist.assign(n, INF);
    cnt.assign(n, 0.0);
    priority_queue<pli, vector<pli>, greater<pli>> pq;
    dist[src] = 0;
    cnt[src] = 1.0;
    pq.push({0, src});
    while (!pq.empty()) {
        auto [d, u] = pq.top(); pq.pop();
        if (d > dist[u]) continue;
        for (auto [v, w] : adj[u]) {
            ll nd = dist[u] + w;
            if (nd < dist[v]) {
                dist[v] = nd;
                cnt[v] = cnt[u];
                pq.push({nd, v});
            } else if (nd == dist[v]) {
                cnt[v] += cnt[u];
            }
        }
    }
}

