const ll INF = (1LL << 62);

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m, p;
    cin >> n >> m >> p;

    vector<vector<pair<int,int>>> g(n);
    for (int i = 0; i < m; ++i) {
        int u, v, w;
        cin >> u >> v >> w;
        g[u].push_back({v, w});
        g[v].push_back({u, w});
    }

    vector<int> children(p);
    for (int i = 0; i < p; ++i) cin >> children[i];

    auto dijkstra = [&](int src) {
        vector<ll> dist(n, INF);
        priority_queue<pair<ll,int>, vector<pair<ll,int>>, greater<pair<ll,int>>> pq;
        dist[src] = 0;
        pq.push({0, src});

        while (!pq.empty()) {
            auto [d, u] = pq.top();
            pq.pop();
            if (d != dist[u]) continue;

            for (auto [v, w] : g[u]) {
                if (dist[v] > d + w) {
                    dist[v] = d + w;
                    pq.push({dist[v], v});
                }
            }
        }
        return dist;
    };

    vector<ll> d0 = dijkstra(0);
    vector<ll> d1 = dijkstra(n - 1);

    ll shortest = d0[n - 1];

    vector<int> order(n);
    iota(order.begin(), order.end(), 0);
    sort(order.begin(), order.end(), [&](int a, int b) {
        if (d0[a] != d0[b]) return d0[a] < d0[b];
        return a < b;
    });

    // Count number of shortest paths from 0 to every node in the shortest-path DAG
    vector<long double> waysFromStart(n, 0.0L), waysToEnd(n, 0.0L);
    waysFromStart[0] = 1.0L;

    for (int u : order) {
        if (d0[u] == INF) continue;
        for (auto [v, w] : g[u]) {
            if (d0[u] + w == d0[v] && d0[u] + w + d1[v] == shortest) {
                waysFromStart[v] += waysFromStart[u];
            }
        }
    }

    // Count number of shortest paths from every node to n-1 in the shortest-path DAG
    vector<int> orderRev = order;
    reverse(orderRev.begin(), orderRev.end());
    waysToEnd[n - 1] = 1.0L;

    for (int u : orderRev) {
        if (d0[u] == INF) continue;
        for (auto [v, w] : g[u]) {
            if (d0[u] + w == d0[v] && d0[u] + w + d1[v] == shortest) {
                waysToEnd[u] += waysToEnd[v];
            }
        }
    }

    long double totalWays = waysFromStart[n - 1];

    cout << fixed << setprecision(10);
    for (int x : children) {
        long double ans = 0.0L;
        if (d0[x] + d1[x] == shortest && totalWays > 0.0L) {
            ans = (waysFromStart[x] * waysToEnd[x]) / totalWays;
        }
        cout << (double)ans << "\n";
    }

    return 0;
}

