HeapNode heap[2 * MAXM];
int heap_size;

void heap_push(HeapNode hn) {
    int i = heap_size++;
    while (i > 0) {
        int p = (i - 1) / 2;
        if (heap[p].dist <= hn.dist) break;
        heap[i] = heap[p];
        i = p;
    }
    heap[i] = hn;
}

HeapNode heap_pop() {
    HeapNode top = heap[0];
    HeapNode last = heap[--heap_size];
    int i = 0;
    while (i * 2 + 1 < heap_size) {
        int left = i * 2 + 1;
        int right = i * 2 + 2;
        int small = left;
        if (right < heap_size && heap[right].dist < heap[left].dist)
            small = right;
        if (heap[small].dist >= last.dist) break;
        heap[i] = heap[small];
        i = small;
    }
    heap[i] = last;
    return top;
}

