#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef long long ll;

typedef struct Edge {
    int to;
    ll w;
    int next;
} Edge;

typedef struct {
    int v;
    ll d;
} HeapNode;

static const ll INF = (1LL << 62);

int n, m, p;
int *head, edgeCnt = 0;
Edge *edges;

void addEdge(int u, int v, ll w) {
    edges[edgeCnt].to = v;
    edges[edgeCnt].w = w;
    edges[edgeCnt].next = head[u];
    head[u] = edgeCnt++;
}

typedef struct {
    HeapNode *a;
    int sz;
} MinHeap;

void heapInit(MinHeap *h, int cap) {
    h->a = (HeapNode *)malloc(sizeof(HeapNode) * (cap + 5));
    h->sz = 0;
}

void heapPush(MinHeap *h, int v, ll d) {
    int i = ++h->sz;
    while (i > 1 && h->a[i / 2].d > d) {
        h->a[i] = h->a[i / 2];
        i /= 2;
    }
    h->a[i].v = v;
    h->a[i].d = d;
}

HeapNode heapPop(MinHeap *h) {
    HeapNode ret = h->a[1];
    HeapNode last = h->a[h->sz--];
    int i = 1, child;
    while ((i << 1) <= h->sz) {
        child = i << 1;
        if (child + 1 <= h->sz && h->a[child + 1].d < h->a[child].d) child++;
        if (h->a[child].d >= last.d) break;
        h->a[i] = h->a[child];
        i = child;
    }
    h->a[i] = last;
    return ret;
}

void dijkstra(int src, ll *dist) {
    for (int i = 0; i < n; i++) dist[i] = INF;
    dist[src] = 0;

    MinHeap h;
    heapInit(&h, 2 * m + 10);
    heapPush(&h, src, 0);

    while (h.sz) {
        HeapNode cur = heapPop(&h);
        int u = cur.v;
        ll d = cur.d;
        if (d != dist[u]) continue;

        for (int e = head[u]; e != -1; e = edges[e].next) {
            int v = edges[e].to;
            ll nd = d + edges[e].w;
            if (nd < dist[v]) {
                dist[v] = nd;
                heapPush(&h, v, nd);
            }
        }
    }
    free(h.a);
}

int cmpDist(const void *a, const void *b, void *arg) {
    ll *dist = (ll *)arg;
    int x = *(const int *)a;
    int y = *(const int *)b;
    if (dist[x] < dist[y]) return -1;
    if (dist[x] > dist[y]) return 1;
    return x - y;
}

int main() {
    if (scanf("%d %d %d", &n, &m, &p) != 3) return 0;

    head = (int *)malloc(sizeof(int) * n);
    edges = (Edge *)malloc(sizeof(Edge) * (2 * m));
    for (int i = 0; i < n; i++) head[i] = -1;

    for (int i = 0; i < m; i++) {
        int u, v;
        ll w;
        scanf("%d %d %lld", &u, &v, &w);
        addEdge(u, v, w);
        addEdge(v, u, w);
    }

    int *children = (int *)malloc(sizeof(int) * p);
    for (int i = 0; i < p; i++) scanf("%d", &children[i]);

    ll *distS = (ll *)malloc(sizeof(ll) * n);
    ll *distT = (ll *)malloc(sizeof(ll) * n);

    dijkstra(0, distS);
    dijkstra(n - 1, distT);

    ll shortest = distS[n - 1];

    int *order = (int *)malloc(sizeof(int) * n);
    for (int i = 0; i < n; i++) order[i] = i;

#if defined(__GNUC__)
    qsort_r(order, n, sizeof(int), cmpDist, distS);
#else
    /* Portable fallback: simple O(n^2) sort if qsort_r unavailable */
    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {
            int xi = order[i], xj = order[j];
            if (distS[xj] < distS[xi] || (distS[xj] == distS[xi] && xj < xi)) {
                int tmp = order[i];
                order[i] = order[j];
                order[j] = tmp;
            }
        }
    }
#endif

    double *waysFromStart = (double *)calloc(n, sizeof(double));
    double *waysToEnd = (double *)calloc(n, sizeof(double));
    waysFromStart[0] = 1.0;

    for (int ii = 0; ii < n; ii++) {
        int u = order[ii];
        if (distS[u] == INF) continue;
        for (int e = head[u]; e != -1; e = edges[e].next) {
            int v = edges[e].to;
            ll w = edges[e].w;
            if (distS[u] + w == distS[v]) {
                waysFromStart[v] += waysFromStart[u];
            }
        }
    }

    waysToEnd[n - 1] = 1.0;
    for (int ii = n - 1; ii >= 0; ii--) {
        int u = order[ii];
        if (distS[u] == INF) continue;
        for (int e = head[u]; e != -1; e = edges[e].next) {
            int v = edges[e].to;
            ll w = edges[e].w;
            if (distS[u] + w == distS[v]) {
                waysToEnd[u] += waysToEnd[v];
            }
        }
    }

    double totalWays = waysFromStart[n - 1];

    for (int i = 0; i < p; i++) {
        int u = children[i];
        double ans = 0.0;
        if (distS[u] != INF && distT[u] != INF && distS[u] + distT[u] == shortest && totalWays > 0.0) {
            ans = (waysFromStart[u] * waysToEnd[u]) / totalWays;
        }
        printf("%.10f\n", ans);
    }

    free(head);
    free(edges);
    free(children);
    free(distS);
    free(distT);
    free(order);
    free(waysFromStart);
    free(waysToEnd);

    return 0;
}

