public class SantaDelivery {
    static final long INF = Long.MAX_VALUE / 2;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();
        int p = sc.nextInt();

        List<int[]>[] graph = new ArrayList[n];
        for (int i = 0; i < n; i++) graph[i] = new ArrayList<>();

        for (int i = 0; i < m; i++) {
            int u = sc.nextInt();
            int v = sc.nextInt();
            int w = sc.nextInt();
            graph[u].add(new int[]{v, w});
            graph[v].add(new int[]{u, w});
        }

        int[] children = new int[p];
        for (int i = 0; i < p; i++) children[i] = sc.nextInt();

        // Dijkstra from source 0
        long[] distFromStart = dijkstra(0, n, graph);
        // Dijkstra from target n-1
        long[] distFromEnd = dijkstra(n - 1, n, graph);

        long shortestDist = distFromStart[n - 1];
        if (shortestDist == INF) {
            for (int i = 0; i < p; i++) System.out.println("0.0");
            return;
        }

        // Count number of shortest paths from start and from end
        long[] waysFromStart = countWays(0, n, graph, distFromStart, shortestDist);
        long[] waysFromEnd = countWays(n - 1, n, graph, distFromEnd, shortestDist);

        long totalWays = waysFromStart[n - 1];

        for (int child : children) {
            if (distFromStart[child] + distFromEnd[child] != shortestDist) {
                System.out.println("0.0");
            } else {
                double prob = (double) waysFromStart[child] * waysFromEnd[child] / totalWays;
                System.out.println(String.format("%.10f", prob));
            }
        }
    }

    static long[] dijkstra(int start, int n, List<int[]>[] graph) {
        long[] dist = new long[n];
        Arrays.fill(dist, INF);
        dist[start] = 0;
        PriorityQueue<long[]> pq = new PriorityQueue<>(Comparator.comparingLong(a -> a[1]));
        pq.offer(new long[]{start, 0});

        while (!pq.isEmpty()) {
            long[] cur = pq.poll();
            int u = (int) cur[0];
            long d = cur[1];
            if (d != dist[u]) continue;
            for (int[] edge : graph[u]) {
                int v = edge[0], w = edge[1];
                if (dist[u] + w < dist[v]) {
                    dist[v] = dist[u] + w;
                    pq.offer(new long[]{v, dist[v]});
                }
            }
        }
        return dist;
    }

    static long[] countWays(int start, int n, List<int[]>[] graph, long[] dist, long targetDist) {
        long[] ways = new long[n];
        ways[start] = 1;
        Integer[] order = new Integer[n];
        for (int i = 0; i < n; i++) order[i] = i;
        Arrays.sort(order, Comparator.comparingLong(i -> dist[i]));

        for (int u : order) {
            if (dist[u] == INF) continue;
            for (int[] edge : graph[u]) {
                int v = edge[0], w = edge[1];
                if (dist[u] + w == dist[v]) {
                    ways[v] += ways[u];
                }
            }
        }
        return ways;
    }
}

