        // Count paths from start and from end
        double[] cs = countPaths(n, adj, ds, de, total, true);
        double[] ce = countPaths(n, adj, de, ds, total, false);

        double totalPaths = cs[n - 1];

        int p = sc.nextInt();
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < p; i++) {
            int node = sc.nextInt();
            double prob = (cs[node] * ce[node]) / totalPaths;
            sb.append(String.format("%.9f\n", prob));
        }
        System.out.print(sb);
    }

    static long[] dijkstra(int n, List<int[]>[] adj, int src) {
        long[] dist = new long[n];
        Arrays.fill(dist, Long.MAX_VALUE / 2);
        dist[src] = 0;
        PriorityQueue<long[]> pq = new PriorityQueue<>(Comparator.comparingLong(a -> a[0]));
        pq.offer(new long[]{0, src});
        while (!pq.isEmpty()) {
            long[] cur = pq.poll();
            long d = cur[0]; int u = (int) cur[1];
            if (d > dist[u]) continue;
            for (int[] e : adj[u]) {
                int v = e[0]; long nd = d + e[1];
                if (nd < dist[v]) { dist[v] = nd; pq.offer(new long[]{nd, v}); }
            }
        }
        return dist;
    }

    static double[] countPaths(int n, List<int[]>[] adj, long[] dist, long[] distOther, long total, boolean fromStart) {
        double[] cnt = new double[n];
        int src = fromStart ? 0 : n - 1;
        cnt[src] = 1;
        // Process nodes in order of dist
        Integer[] order = new Integer[n];
        for (int i = 0; i < n; i++) order[i] = i;
        Arrays.sort(order, Comparator.comparingLong(a -> dist[a]));
        for (int u : order) {
            if (dist[u] + distOther[u] > total) continue;
            for (int[] e : adj[u]) {
                int v = e[0]; long w = e[1];
                if (dist[u] + w == dist[v] && dist[v] + distOther[v] <= total) {
                    cnt[v] += cnt[u];
                }
            }
        }
        return cnt;
    }
}

import java.io.*;
import java.util.*;

/*
We need probabilities that each queried node belongs to a uniformly random shortest path
from 0 to n-1 in an undirected weighted graph.

Idea:
1) Run Dijkstra from source 0 and from target n-1.
2) Let D = dist0[n-1]. An edge (u,v,w) can be used in some shortest path DAG direction u->v iff
      dist0[u] + w + dist1[v] == D
   and dist0[u] < dist0[v]
   (similarly v->u if reversed).
   Since weights are positive, distances strictly increase along such edges, so this forms a DAG.
3) Count number of shortest paths from source to every node in this DAG: waysFromStart.
4) Count number of shortest paths from every node to target in this DAG: waysToEnd.
5) Total shortest paths = waysFromStart[target].
   Number through node x = waysFromStart[x] * waysToEnd[x].
   Probability = through / total.

Counts can be enormous, so we avoid exact big integers by using modular arithmetic with two mods.
For comparison / zero testing, pair of mods is enough in contest practice.
Probability is printed as double:
   (waysStart[x]/total) * waysEnd[x]
We compute with logs? No, modular counts are only for path existence/count identity, not numeric ratio.

But problem asks probability, so we need actual numeric value.
Typical solution: count shortest paths in doubles because only ratios matter and DAG sums of counts.
We can safely use double for path counts unless astronomically huge; for competitive tasks this is standard.
We'll use double counts for probability, and long distances.

Input format is not explicitly provided in the statement snippet, but standard for this known type is:
n m p
m lines: a b w
p lines: child node
Output one probability per child.

If queried nodes are all vertices, this handles it.
*/

public class Main {
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do c = read(); while (c <= ' ' && c != -1);
            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    static class Edge {
        int to;
        long w;
        Edge(int to, long w) {
            this.to = to;
            this.w = w;
        }
    }

    static class Node implements Comparable<Node> {
        int v;
        long d;
        Node(int v, long d) {
            this.v = v;
            this.d = d;
        }
        public int compareTo(Node o) {
            return Long.compare(this.d, o.d);
        }
    }

    static final long INF = Long.MAX_VALUE / 4;

    static long[] dijkstra(List<Edge>[] g, int src) {
        int n = g.length;
        long[] dist = new long[n];
        Arrays.fill(dist, INF);
        dist[src] = 0;
        PriorityQueue<Node> pq = new PriorityQueue<>();
        pq.add(new Node(src, 0));

        while (!pq.isEmpty()) {
            Node cur = pq.poll();
            if (cur.d != dist[cur.v]) continue;
            for (Edge e : g[cur.v]) {
                long nd = cur.d + e.w;
                if (nd < dist[e.to]) {
                    dist[e.to] = nd;
                    pq.add(new Node(e.to, nd));
                }
            }
        }
        return dist;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        int n = fs.nextInt();
        int m = fs.nextInt();
        int p = fs.nextInt();

        List<Edge>[] g = new ArrayList[n];
        for (int i = 0; i < n; i++) g[i] = new ArrayList<>();

        int[] eu = new int[m];
        int[] ev = new int[m];
        long[] ew = new long[m];

        for (int i = 0; i < m; i++) {
            int a = fs.nextInt();
            int b = fs.nextInt();
            long w = fs.nextLong();
            eu[i] = a;
            ev[i] = b;
            ew[i] = w;
            g[a].add(new Edge(b, w));
            g[b].add(new Edge(a, w));
        }

        int[] queries = new int[p];
        for (int i = 0; i < p; i++) queries[i] = fs.nextInt();

        long[] dist0 = dijkstra(g, 0);
        long[] dist1 = dijkstra(g, n - 1);
        long D = dist0[n - 1];

        Integer[] order = new Integer[n];
        for (int i = 0; i < n; i++) order[i] = i;
        Arrays.sort(order, Comparator.comparingLong(a -> dist0[a]));

        double[] waysFromStart = new double[n];
        waysFromStart[0] = 1.0;

        for (int idx = 0; idx < n; idx++) {
            int u = order[idx];
            if (dist0[u] == INF || waysFromStart[u] == 0.0) continue;
            for (Edge e : g[u]) {
                int v = e.to;
                if (dist0[u] + e.w + dist1[v] == D && dist0[u] < dist0[v]) {
                    waysFromStart[v] += waysFromStart[u];
                }
            }
        }

        Arrays.sort(order, (a, b) -> Long.compare(dist0[b], dist0[a]));
        double[] waysToEnd = new double[n];
        waysToEnd[n - 1] = 1.0;

        for (int idx = 0; idx < n; idx++) {
            int u = order[idx];
            if (dist0[u] == INF) continue;
            for (Edge e : g[u]) {
                int v = e.to;
                if (dist0[u] + e.w + dist1[v] == D && dist0[u] < dist0[v]) {
                    waysToEnd[u] += waysToEnd[v];
                }
            }
        }

        double total = waysFromStart[n - 1];
        StringBuilder sb = new StringBuilder();
        for (int x : queries) {
            double ans = 0.0;
            if (total > 0) ans = (waysFromStart[x] * waysToEnd[x]) / total;
            sb.append(String.format(Locale.US, "%.10f%n", ans));
        }
        System.out.print(sb.toString());
    }
}

import sys
import heapq
from collections import defaultdict, deque

input = sys.stdin.readline

MOD = 10**9 + 7

def dijkstra(start, n, graph):
    dist = [float('inf')] * n
    dist[start] = 0
    pq = [(0, start)]
    while pq:
        d, u = heapq.heappop(pq)
        if d != dist[u]:
            continue
        for v, w in graph[u]:
            nd = d + w
            if nd < dist[v]:
                dist[v] = nd
                heapq.heappush(pq, (nd, v))
    return dist

def count_ways(start, dist, n, graph):
    ways = [0] * n
    ways[start] = 1
    order = sorted(range(n), key=lambda x: dist[x])
    for u in order:
        if dist[u] == float('inf'):
            continue
        for v, w in graph[u]:
            if dist[v] == dist[u] + w:
                ways[v] = (ways[v] + ways[u]) % MOD
    return ways

def main():
    n, m, p = map(int, input().split())
    graph = [[] for _ in range(n)]
    for _ in range(m):
        a, b, c = map(int, input().split())
        graph[a].append((b, c))
        graph[b].append((a, c))

    children = [int(input()) for _ in range(p)]

    dist_from_start = dijkstra(0, n, graph)
    dist_to_end = dijkstra(n - 1, n, graph)
    shortest_dist = dist_from_start[n - 1]

    if shortest_dist == float('inf'):
        for _ in range(p):
            print(0)
        return

    ways_from_start = count_ways(0, dist_from_start, n, graph)
    # Reverse graph for reverse counting
    rev_graph = [[] for _ in range(n)]
    for u in range(n):
        for v, w in graph[u]:
            rev_graph[v].append((u, w))
    ways_to_end = count_ways(n - 1, dist_to_end, n, rev_graph)

    total_ways = ways_from_start[n - 1]

    for c in children:
        if dist_from_start[c] + dist_to_end[c] != shortest_dist:
            print(0)
        else:
            num = (ways_from_start[c] * ways_to_end[c]) % MOD
            # Probability as float division
            prob = num / total_ways
            print(f"{prob:.10f}")

if __name__ == "__main__":
    main()
